# -*- coding: utf-8 -*-
"""
Generates 160 realistic, high-quality Indian Government schemes across Central and State levels
with full translations in English, Hindi, Marathi, and Tamil.
Appends them to data/schemes.json to reach 180+ total schemes.
"""
import json
import os

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
SCHEMES_FILE = os.path.join(BASE_DIR, "data", "schemes.json")

with open(SCHEMES_FILE, "r", encoding="utf-8") as f:
    existing_schemes = json.load(f)

existing_ids = set(s["id"] for s in existing_schemes)
print(f"Starting with {len(existing_schemes)} existing schemes.")

# List of 160 schemes data
new_schemes = []

def add_s(sid, scope, state, rule, en_name, en_tag, en_desc, en_ben, en_doc, en_stp, en_lnk,
          hi_name, hi_tag, hi_desc, hi_ben, hi_doc, hi_stp,
          mr_name, mr_tag, mr_desc, mr_ben, mr_doc, mr_stp,
          ta_name, ta_tag, ta_desc, ta_ben, ta_doc, ta_stp):
    if sid in existing_ids:
        return
    new_schemes.append({
        "id": sid,
        "scope": scope,
        "state": state,
        "rule": rule,
        "t": {
            "en": {"name": en_name, "tag": en_tag, "desc": en_desc, "benefits": en_ben, "documents": en_doc, "steps": en_stp, "link": en_lnk},
            "hi": {"name": hi_name, "tag": hi_tag, "desc": hi_desc, "benefits": hi_ben, "documents": hi_doc, "steps": hi_stp, "link": en_lnk},
            "mr": {"name": mr_name, "tag": mr_tag, "desc": mr_desc, "benefits": mr_ben, "documents": mr_doc, "steps": mr_stp, "link": en_lnk},
            "ta": {"name": ta_name, "tag": ta_tag, "desc": ta_desc, "benefits": ta_ben, "documents": ta_doc, "steps": ta_stp, "link": en_lnk}
        }
    })

